 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(x == v for row in grid for x in row))
    out = [row[:] for row in grid]
    # A full horizontal marker row: draw an 8 row just below the object.
    hr = next((r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg), None)
    if hr is not None:
        mc = grid[hr][0]
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, mc)]
        if cells:
            rr = max(r for r, c in cells) + 1
            if rr < h:
                out[rr] = [8] * w
        return out
    # Full vertical marker column: move the object next to it and insert 8 separator.
    vc = next((c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg), None)
    if vc is not None:
        mc = grid[0][vc]
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, mc)]
        if cells:
            cmin = min(c for r, c in cells)
            dest_min = vc + 1
            shift = cmin - dest_min
            for r, c in cells:
                out[r][c] = bg
            for r, c in cells:
                out[r][c-shift] = grid[r][c]
            mark = dest_min + (max(c for r, c in cells) - cmin) + 1
            if mark < w:
                for r in range(h):
                    out[r][mark] = 8
    return out
